// Some portions generated by Codex
package org.eclipse.rdf4j.query.impl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.Set;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.Dataset;
import org.junit.jupiter.api.Test;

class BlankNodeDatasetCompatibilityTest {
	@Test
	void retainedLegacyViewTracksMutationsAndRejectsLossyAccess() {
		var vf = SimpleValueFactory.getInstance();
		var dataset = new SimpleDataset();
		IRI first = vf.createIRI("urn:first");
		IRI second = vf.createIRI("urn:second");
		dataset.addNamedGraph(first);
		Set<IRI> retained = dataset.getNamedGraphs();
		dataset.addNamedGraph(second);
		assertEquals(Set.of(first, second), retained, "the old unmodifiable set remains a live view");
		assertThrows(UnsupportedOperationException.class, () -> retained.add(vf.createIRI("urn:third")));
		dataset.addNamedGraph(vf.createBNode("graph"));
		assertThrows(IllegalStateException.class, retained::size, "a retained view must not omit blank-node names");
	}

	@Test
	void legacyNullSetsRemainUsableWithFallback() {
		Dataset legacy = new Dataset() {
			public Set<IRI> getDefaultGraphs() {
				return null;
			}

			public Set<IRI> getNamedGraphs() {
				return null;
			}

			public Set<IRI> getDefaultRemoveGraphs() {
				return null;
			}

			public IRI getDefaultInsertGraph() {
				return null;
			}
		};
		var fallback = new SimpleDataset();
		var graph = SimpleValueFactory.getInstance().createIRI("urn:graph");
		fallback.addDefaultGraph(graph);
		fallback.addNamedGraph(graph);
		fallback.addDefaultRemoveGraph(graph);
		Dataset dataset = FallbackDataset.fallback(legacy, fallback);
		assertEquals(Set.of(graph), dataset.getDefaultGraphResources());
		assertEquals(Set.of(graph), dataset.getNamedGraphResources());
		assertEquals(Set.of(graph), dataset.getDefaultRemoveGraphResources());
	}
}
